Item.method_code:
const { item, itemNode, itemTypeName } = options;

if ((!item && !itemNode)) {
	return false;
}
const id = item?.id ?? itemNode.id;
const isEditState = ArasModules.item.isEditState(itemTypeName, id);

if (!isEditState) {
	const unlockCommand = commands.commandFactory('UnlockItem', options);
	return unlockCommand.canExecute();
}

const canExecute = ArasModules.item.isEditedAndClaimed(itemTypeName, id);
return canExecute;
